message.content:
{
"css": ".planner-header {
  padding: 24px var(--screen-inset) 0;
}

.planner-header h1 {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.5;
  text-align: left;
  margin-bottom: 16px;
  color: var(--text);
}

.week-strip {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  width: 100%;
  padding: 4px 0;
  /* Hide scrollbar for cleaner mobile look while maintaining scroll functionality */
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.week-strip::-webkit-scrollbar {
  display: none;
}

.day-button {
  flex: 0 0 44px;
  min-height: 64px;
  background: transparent;
  border: none;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0;
  font-family: inherit;
}

.day-button .weekday {
  font-size: 14px;
  font-weight: 500;
  color: var(--muted);
  line-height: 1;
}

.day-button .day-number {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  background-color: transparent;
}

/* Selected State */
.day-button[aria-pressed="true"] .day-number {
  background-color: var(--text);
  color: #fff;
  font-weight: 700;
}

.day-button[aria-pressed="true"] .weekday {
  color: var(--text);
}

/* Focus State */
.day-button:focus-visible {
  outline: none;
}

.day-button:focus-visible .day-number {
  box-shadow: 0 0 0 2px var(--surface), 0 0 0 4px var(--focus);
}

/* Hide native scrollbar for week-strip */
.week-strip::-webkit-scrollbar {
  display: none;
}"
}
